
const KEY='gestao_menezes_v21_editar_vendas';
// O cache é opcional: fotos grandes podem exceder a cota do navegador.
function cacheStateLocally(snapshot){
 try{localStorage.setItem(KEY,JSON.stringify(snapshot));return true}
 catch(error){console.warn('Cache local indisponível. Dados principais seguem no servidor.',error?.name||error);return false}
}

let accessRole='viewer';
let serverRevision=0;
let remoteReady=false;
let saveQueue=Promise.resolve();
function isManager(){return accessRole==='manager'}
function canAddSale(){return isManager()||accessRole==='trainee'}
function canDeleteSale(){return isManager()||accessRole==='trainee'}
function canViewLeaders(){return isManager()||accessRole==='trainee'}
function requireManager(){if(isManager())return true;alert('Somente o gestor pode alterar estes dados.');return false}
function applyAccessRole(role){
 accessRole=role==='gestor'?'manager':role==='trainee'?'trainee':'viewer';document.body.dataset.role=accessRole;
 const label=document.getElementById('accessRoleLabel'),box=document.getElementById('accessRoleBox');
 if(label)label.textContent=isManager()?'Gestor':accessRole==='trainee'?'Trainee':'Consultor';
 if(box)box.classList.toggle('manager',isManager());
  // O visual da aba Equipe é o mesmo para os três perfis.
  // Apenas o Gestor pode interagir com as ferramentas administrativas.
  document.querySelectorAll('#team .manager-only').forEach(el=>{
    if(isManager()){el.removeAttribute('inert');el.removeAttribute('aria-disabled');}
    else {el.setAttribute('inert','');el.setAttribute('aria-disabled','true');}
  });
 const note=document.querySelector('.viewer-note');if(note)note.textContent=accessRole==='trainee'?'Modo Trainee: permitido cadastrar e excluir vendas; demais alterações são exclusivas do gestor.':'Modo Consultor: somente visualização.';
 const current=[...document.querySelectorAll('.view')].find(v=>!v.classList.contains('hidden'))?.id;
 if((current==='settings'&&!isManager())||(current==='leaders'&&!canViewLeaders())||(current==='sale'&&!canAddSale()))switchView('dashboard');
}
async function apiJSON(url,method='GET',payload){
 const res=await fetch(url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},body:payload?JSON.stringify(payload):undefined,cache:'no-store'});
 let data={};try{data=await res.json()}catch{}
 if(!res.ok)throw new Error(data.error||'Erro no servidor');return data;
}
async function refreshShared(){
 const remote=await apiJSON('/api/state');
 if(remote.state){state=remote.state;serverRevision=remote.revision;remoteReady=true;try{cacheStateLocally(state)}catch(e){console.warn('Cache local indisponível',e)}render();return true}
 return false;
}
async function loginWithRole(role,password){
 await apiJSON('/api/session','POST',{role,password});
 const verified=await apiJSON('/api/session');
 if(verified.role!==role)throw new Error('Senha validada, mas o navegador não manteve a sessão. Habilite cookies para este site ou abra-o em janela privativa.');
 applyAccessRole(role);
 let found=false;
 try{found=await refreshShared()}catch(err){
  console.error('Falha ao ler base compartilhada após login',err);
  remoteReady=false;
  document.getElementById('gmAuth').classList.add('hidden');
  applyAccessRole('consultor');
  const host=document.querySelector('.main')||document.body;
  let warning=document.getElementById('gmSyncOffline');
  if(!warning){warning=document.createElement('div');warning.id='gmSyncOffline';warning.style.cssText='margin:0 0 20px;padding:16px 18px;border:1px solid #e5b75c;background:#302312;color:#ffe0a5;border-radius:14px;line-height:1.6;font-size:13px;font-weight:650';host.prepend(warning)}
  warning.textContent='A senha foi aceita, mas a base compartilhada não pôde ser carregada ('+String(err.message||'erro de conexão')+'). Os dados exibidos são somente uma cópia local e podem estar desatualizados. Edição bloqueada. Recarregue a página para tentar sincronizar.';
  try{render()}catch(e){console.error('Erro ao exibir cópia local',e)}
  return;
 }
 if(!found){
  if(role==='gestor'){
   let hasLocal=false;try{hasLocal=Boolean(localStorage.getItem(KEY))}catch{}
   if(!confirm('Ainda não existe uma base compartilhada. Deseja importar os dados '+(hasLocal?'deste navegador':'iniciais')+' para a equipe agora? Verifique se este é o navegador que contém as vendas corretas.'))throw new Error('Importação inicial necessária para ativar os acessos.');
   const data=await apiJSON('/api/state','POST',{action:'initialize',state});serverRevision=data.revision;remoteReady=true;
  }else throw new Error('O gestor precisa importar a base de vendas antes de liberar os acessos.');
 }
 document.getElementById('gmAuth').classList.add('hidden');
 try{render()}catch(e){console.error('Erro ao atualizar dashboard após login',e)}
}
async function requestManagerAccess(){await logoutAccess()}
async function logoutAccess(){try{await apiJSON('/api/session','DELETE')}catch{}applyAccessRole('consultor');document.getElementById('gmAuth').classList.remove('hidden');document.getElementById('gmAuthPassword').value='';}
async function startAuth(){
 const auth=document.getElementById('gmAuth'),err=document.getElementById('gmAuthError');auth.classList.remove('hidden');
 document.getElementById('gmAuthForm').onsubmit=async e=>{
  e.preventDefault();err.textContent='';const btn=document.getElementById('gmAuthSubmit');btn.disabled=true;btn.textContent='Validando...';
  try{await loginWithRole(document.getElementById('gmAuthRole').value,document.getElementById('gmAuthPassword').value)}catch(e){err.textContent=e.message;}
  finally{btn.disabled=false;btn.textContent='Entrar no dashboard'}
 };
 try{const s=await apiJSON('/api/session');if(s.role){applyAccessRole(s.role);if(await refreshShared())auth.classList.add('hidden')}}catch(e){err.textContent='O acesso ainda não está configurado. Cadastre as variáveis de ambiente e configure o armazenamento.'}
}

