function restorePublishedTeamPhotos(target){
  const addMissing=!target._publishedTeamPhotos20261101;
  for(const profile of publishedTeamPhotos){
    let c=target.consultants.find(item=>item.id===profile.id);
    if(!c && addMissing){
      c={...profile,opening:0,openingLar:0,openingMotors:0,openingLarQty:0,openingMotorsQty:0,openingUnclassifiedQty:0};
      target.consultants.push(c);
    }
    if(c && !c.photo && profile.photo)c.photo=profile.photo;
  }
  target._publishedTeamPhotos20261101=true;
}
