function ensureHierarchy(){
  const defaults={
    mateus:{role:'gestor',leaderId:null},
    asafe:{role:'trainee',leaderId:'mateus'},
    rodrigo:{role:'trainee',leaderId:'mateus'},
    gabrielle:{role:'trainee',leaderId:'mateus'},
    fatima:{role:'consultor',leaderId:'asafe'}
  };
  state.consultants=(state.consultants||[]).map(c=>{
    const d=defaults[c.id];
    if(d) return {...c,...d};
    return {...c,role:c.role||'consultor',gender:c.gender||'',leaderId:c.leaderId??null,openingLarQty:Number(c.openingLarQty)||0,openingMotorsQty:Number(c.openingMotorsQty)||0,openingUnclassifiedQty:Number(c.openingUnclassifiedQty)||0,enrollmentStatus:c.enrollmentStatus||'sem',enrollmentNumber:c.enrollmentNumber||''};
  });
}
