 const photoWrap=document.getElementById('consultantPhotoCard'); const photoImg=document.getElementById('consultantPhotoImg'); const photoInitials=document.getElementById('consultantPhotoInitials'); photoInitials.textContent=initials(c.name); if(c.photo){photoWrap.classList.add('has-image');photoImg.src=c.photo;}else{photoWrap.classList.remove('has-image');photoImg.removeAttribute('src');}
 const photoInput=document.getElementById('consultantPhotoInput'); if(photoInput){photoInput.value='';photoInput.onchange=e=>{if(!requireManager())return;const file=e.target.files&&e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const targetConsultant=state.consultants.find(x=>x.id===consultantFocusId);if(!targetConsultant)return;targetConsultant.photo=reader.result;save();renderTeam();};reader.readAsDataURL(file);};}
