function updateSaleTotalPreview(){
 const unitAmount=Math.max(0,parseNumber(document.getElementById('saleAmount')?.value)||0);
 const qty=Math.max(1,Math.round(Number(document.getElementById('saleQty')?.value)||1));
 const total=unitAmount*qty;
 const preview=document.getElementById('saleTotalPreview');
 const formula=document.getElementById('saleTotalFormula');
 if(preview)preview.textContent=money(total);
 if(formula)formula.textContent=qty+' cota'+(qty===1?'':'s')+' × '+money(unitAmount);
}
document.getElementById('saleAmount').addEventListener('input',updateSaleTotalPreview);
document.getElementById('saleAmount').addEventListener('blur',updateSaleTotalPreview);
document.getElementById('saleQty').addEventListener('input',updateSaleTotalPreview);
updateSaleTotalPreview();

let saleSaveInFlight=false;
let pendingSaleEntry=null;
async function saveSaleEntry(shareRanking=false){
 if(saleSaveInFlight)return;
 if(!canAddSale()){alert('Somente Gestor ou Trainee podem lançar vendas.');return}
 if(!remoteReady){alert('A base compartilhada não está disponível.');return}
 const consultantId=document.getElementById('saleConsultant').value;
 const product=document.getElementById('saleProduct').value;
 const unitAmount=parseNumber(document.getElementById('saleAmount').value);
 const qty=Math.max(0,Math.round(Number(document.getElementById('saleQty').value)||0));
 const date=document.getElementById('saleDate').value;
 const note=document.getElementById('saleNote').value.trim();
 if(!consultantId||!unitAmount||unitAmount<=0||!qty||!date){alert('Preencha consultor, valor por cota, quantidade de cotas e data.');return}
 const amount=unitAmount*qty;
 const fields={consultantId,product,amount,unitAmount,qty,date,note};
 const fingerprint=JSON.stringify(fields);
 if(!pendingSaleEntry||pendingSaleEntry.fingerprint!==fingerprint){
  pendingSaleEntry={fingerprint,sale:{id:'s'+crypto.randomUUID(),...fields}};
 }
 const sale=pendingSaleEntry.sale;
 saleSaveInFlight=true;
 const saveButtons=['saveSale','saveSaleShare'].map(id=>document.getElementById(id));
 saveButtons.forEach(btn=>{if(btn)btn.disabled=true;});
 try{
  await saveQueue;
  const result=await apiJSON('/api/state','POST',{action:'addSale',sale});
  state=result.state;serverRevision=result.revision;
  cacheStateLocally(state);
 }catch(error){alert('Não foi possível confirmar a venda: '+error.message+' Tente novamente sem alterar os campos para conferir o mesmo lançamento.');return}
 finally{saleSaveInFlight=false;saveButtons.forEach(btn=>{if(btn)btn.disabled=false;});}
 pendingSaleEntry=null;
 document.getElementById('saleAmount').value='';
 document.getElementById('saleQty').value='1';
 document.getElementById('saleNote').value='';
 updateSaleTotalPreview();
 document.getElementById('monthFilter').value=monthKey(date);
 render();switchView('dashboard');
 if(shareRanking)prepareRankingShare();else maybeAutoExportRanking();
}
document.getElementById('saveSale').onclick=()=>saveSaleEntry(false);
document.getElementById('saveSaleShare').onclick=()=>saveSaleEntry(true);
document.getElementById('addConsultant').onclick=()=>{
 if(!requireManager())return;
 const name=document.getElementById('newConsultant').value.trim(),opening=Math.max(0,parseNumber(document.getElementById('newBalance').value)||0),target=Math.max(0,parseNumber(document.getElementById('newTarget').value)||state.settings.defaultTarget),leaderId=(document.getElementById('newLeader')?.value||'')||null;
 if(!name){alert('Informe o nome.');return}
 if(leaderId && !state.consultants.some(x=>x.id===leaderId&&(x.role==='gestor'||x.role==='trainee'))){alert('Selecione um responsável válido pela equipe.');return}
 state.consultants.push({id:'c'+Date.now(),name,target,opening,openingLar:0,openingMotors:0,openingLarQty:0,openingMotorsQty:0,openingUnclassifiedQty:0,role:'consultor',leaderId,enrollmentStatus:'sem',enrollmentNumber:''});save();
 document.getElementById('newConsultant').value='';document.getElementById('newBalance').value='';document.getElementById('newTarget').value='';if(document.getElementById('newLeader'))document.getElementById('newLeader').value='';render();
};
function syncSettings(){const s=state.settings;setCurrencyInputValue('cfgTeamTarget',s.teamTarget);setCurrencyInputValue('cfgDefaultTarget',5000000);const w=document.getElementById('cfgSecretaryWhatsapp');if(w)w.value=s.secretaryWhatsapp||''}
document.getElementById('saveSettings').onclick=()=>{
 if(!requireManager())return;
 const map={cfgTeamTarget:'teamTarget'};
 state.settings.defaultTarget=5000000;
 (state.consultants||[]).forEach(c=>{c.target=5000000;});
 for(const[id,key]of Object.entries(map)){const v=parseNumber(document.getElementById(id).value);if(v>=0)state.settings[key]=v}
 const secretaryWhatsapp=document.getElementById('cfgSecretaryWhatsapp');if(secretaryWhatsapp)state.settings.secretaryWhatsapp=String(secretaryWhatsapp.value||'').replace(/\D/g,'');
 save();syncSettings();render();fillSimulator();alert('Configurações salvas.');
};
document.getElementById('exportBackup').onclick=()=>{
 if(!requireManager())return;
 const payload={
   app:'Gestão Menezes',
   version:'v55',
   exportedAt:new Date().toISOString(),
   storageKey:KEY,
   state:clone(state)
 };
 const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'});
 const a=document.createElement('a');
 a.href=URL.createObjectURL(blob);
 a.download=`backup-gestao-menezes-${new Date().toISOString().slice(0,10)}.json`;
 a.click();
 setTimeout(()=>URL.revokeObjectURL(a.href),500);
};
document.getElementById('importBackup').onclick=()=>{
 if(!requireManager())return;
 document.getElementById('importBackupFile').click();
};
document.getElementById('importBackupFile').onchange=e=>{
 if(!requireManager())return;
 const file=e.target.files&&e.target.files[0];
 if(!file)return;
 const reader=new FileReader();
 reader.onload=()=>{
   try{
     const parsed=JSON.parse(reader.result);
     const incoming=parsed&&parsed.state?parsed.state:parsed;
     if(!incoming||!Array.isArray(incoming.consultants)||!Array.isArray(incoming.sales)||!incoming.settings){
       throw new Error('Formato inválido');
     }     state=incoming;
     save();
     init();
     alert('Backup importado com sucesso.');
   }catch(err){
     alert('Não foi possível importar este backup.');
   }finally{
     e.target.value='';
   }
 };
 reader.readAsText(file,'utf-8');
};
document.getElementById('resetData').onclick=()=>{if(!requireManager())return;if(confirm('Restaurar a base inicial desta versão?')){state=clone(initialState);save();init()}};
