function renderCommissionSimulator(){
  const creditEl=document.getElementById('commissionCredit');
  const conditionEl=document.getElementById('commissionCondition');
  if(!creditEl||!conditionEl)return;
  const credit=Math.max(0,parseNumber(creditEl.value)||0);
  const condition=conditionEl.value;
  const baseRate=.02;
  const nf=.1823,iss=.015,totalTaxRate=nf+iss;
  const gross=credit*baseRate;
  const taxes=gross*totalTaxRate;
  const net=Math.max(0,gross-taxes);
  const netPct=credit?(net/credit)*100:0;
  const monthlyGoalCredit=5000000;
  const monthlyGoalNet=monthlyGoalCredit*baseRate*(1-totalTaxRate);
  const annualGoalNet=monthlyGoalNet*12;
  const monthlyGoalEl=document.getElementById('commissionMonthlyNet');
  if(monthlyGoalEl)monthlyGoalEl.textContent=money(monthlyGoalNet);
  const annualGoalEl=document.getElementById('commissionAnnualProjection');
  if(annualGoalEl)annualGoalEl.textContent=money(annualGoalNet)+' líquidos em 12 meses';
  const configs={
    motors13:{count:13,label:'MOTORS • 13x linear',mode:'Distribuição linear',rows:[['Parcelas 01 a 13',baseRate/13,13]]},
    lar100:{count:11,label:'LAR • 100%',mode:'Distribuição linear estimada',rows:[['Parcelas 01 a 11',baseRate/11,11]]},
    lar85:{count:11,label:'LAR • 85%',mode:'Distribuição linear estimada',rows:[['Parcelas 01 a 11',baseRate/11,11]]},
    lar70:{count:13,label:'LAR • 70%',mode:'Distribuição linear estimada',rows:[['Parcelas 01 a 13',baseRate/13,13]]},
    lar50:{count:13,label:'LAR • 50%',mode:'Distribuição diferenciada',rows:[['Parcelas 01 a 10',.001288,10],['Parcelas 11 e 12',.002374,2],['Parcela 13',.002372,1]]}
  };
  const cfg=configs[condition]||configs.lar50;
  document.getElementById('commissionGross').textContent=money(gross);
  document.getElementById('commissionTaxes').textContent=money(taxes);
  document.getElementById('commissionNet').textContent=money(net);
  document.getElementById('commissionParcelCount').textContent=cfg.count+'x';
  document.getElementById('commissionParcelMode').textContent=cfg.mode;
  document.getElementById('commissionNetPct').textContent=netPct.toFixed(2).replace('.',',')+'%';
  document.getElementById('commissionFlowLabel').textContent=cfg.label;
  const readSummary=document.getElementById('commissionReadSummary');
  if(readSummary)readSummary.textContent=money(credit)+' em crédito → '+money(gross)+' bruto → '+money(net)+' líquido aprox.';
  const summaryCredit=document.getElementById('commissionSummaryCredit');
  const summaryGross=document.getElementById('commissionSummaryGross');
  const summaryNet=document.getElementById('commissionSummaryNet');
  if(summaryCredit)summaryCredit.textContent=money(credit);
  if(summaryGross)summaryGross.textContent=money(gross);
  if(summaryNet)summaryNet.textContent=money(net);
  const bars=document.getElementById('commissionBars');
  if(bars){
    const maxRate=Math.max(...cfg.rows.map(r=>r[1]));
    bars.innerHTML=cfg.rows.map(([label,rate,count])=>{
      const each=credit*rate;
      const width=maxRate?Math.max(8,(rate/maxRate)*100):0;
      const rateLabel=(rate*100).toFixed(3).replace('.',',')+'%';
      const valueLabel=count>1?money(each)+' cada':money(each);
      return '<div class="commission-bar-row"><span>'+esc(label)+'</span><div class="commission-bar-track"><i style="width:'+width+'%"></i></div><b>'+rateLabel+' • '+valueLabel+'</b></div>';
    }).join('');
  }
}
const commissionCredit=document.getElementById('commissionCredit');
const commissionCondition=document.getElementById('commissionCondition');
if(commissionCredit){
  commissionCredit.addEventListener('input',renderCommissionSimulator);
  commissionCredit.addEventListener('blur',()=>{const v=Math.max(0,parseNumber(commissionCredit.value)||0);commissionCredit.value=money(v);renderCommissionSimulator();});
}
if(commissionCondition)commissionCondition.addEventListener('change',renderCommissionSimulator);
document.querySelectorAll('[data-commission-credit]').forEach(btn=>btn.addEventListener('click',()=>{
  if(!commissionCredit)return;
  commissionCredit.value=money(Number(btn.dataset.commissionCredit)||0);
  renderCommissionSimulator();
}));
renderCommissionSimulator();

