function init(){
 const now=new Date(),current=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
 document.getElementById('monthFilter').value=current;
 document.getElementById('saleDate').value=now.toISOString().slice(0,10);

  // O login é ativado antes de desenhar o painel.
  applyAccessRole('consultor');startAuth();
  try{syncSettings();render();initCurrencyInputs()}
  catch(error){console.error('Falha visual ao inicializar o painel; login continua ativo',error)}
}
init();
